CREATE TABLE IF NOT EXISTS cliente (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255), telefone VARCHAR(255), idade INTEGER CHECK (idade BETWEEN 0 AND 150), instagram VARCHAR(255));
CREATE TABLE IF NOT EXISTS usuarios (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, nome VARCHAR(255) NOT NULL, email VARCHAR(255) NOT NULL UNIQUE, senha VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS marcacoes (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, cliente_id BIGINT NOT NULL REFERENCES cliente(id), data DATE, horario TIME(6), descricao VARCHAR(255), status VARCHAR(255) CHECK (status IN ('AGENDADA','CONFIRMADA','CONCLUIDA','CANCELADA')));
